import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 kink) public {
        uint256 kinkBound = bound(kink, 1e27, type(uint256).max);
        c.initialize(address(0));
        vm.expectRevert();
        C.SlopeData memory slopes = C.SlopeData({kink: kinkBound, slope0: 0, slope1: 0});
        c.setSlopes(address(0), slopes);
    }
}

