pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _asset, uint256 _kink, uint256 _slope0, uint256 _slope1) public {
        // Bound kink to cover valid and invalid ranges
        _kink = bound(_kink, 0, 2e27);
        // Assume kink is either exactly 0, >= 1e27, or a valid value in (0, 1e27)
        // We want the rule: for any kink that is 0 or >= 1e27, setSlopes must revert
        vm.assume(_kink == 0 || _kink >= 1e27);

        C.SlopeData memory slopes = C.SlopeData({
            kink: _kink,
            slope0: _slope0,
            slope1: _slope1
        });

        // Initialize the contract
        c.initialize(address(0x1));

        // Try to call setSlopes with invalid kink
        bool reverted = false;
        try c.setSlopes(_asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Assert: must revert for invalid kink values
        assertTrue(reverted);
    }
}

