pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 kink) public {
        vm.assume(kink >= 1e27 || kink == 0);
        // Attempt to initialize (required before calling setSlopes)
        c.initialize(address(0));
        // Try to call setSlopes with an invalid kink
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("setSlopes(address,(uint256,uint256,uint256))", address(0), [kink, 0, 0])
        );
        assertTrue(!success, "setSlopes should revert when kink >= 1e27 or kink == 0");
    }
}

